#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class StartupTablesTask final {
public:enum class Kind{Both,Delay,Samples};enum class Stage{DelayChild,SamplesChild,Return,BindConstant,ReadRate,CalculateBase,ClearRemainder,DoubleBase,BindSource,BindTarget,Count,ReadCoefficient,ScaleCoefficient,CopyBase,DivideHigh,RetainHigh,ClearLow,DivideLow,Merge,DoubleResult,Write,Advance,Decrement,Repeat,MultiplyResult,Complete};StartupTablesTask(Kind kind=Kind::Both):kind_(kind),stage_(kind==Kind::Both?Stage::DelayChild:Stage::BindConstant){}Kind kind()const{return kind_;}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned index()const{return index_;}unsigned shiftIndex()const{return shifts_;}uint32_t result()const{return result_;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::DelayChild:case Stage::SamplesChild:return c.shortCall;case Stage::Return:return c.ret;case Stage::BindConstant:return kind_==Kind::Delay?9:6;case Stage::ReadRate:return 9+c.read;case Stage::CalculateBase:case Stage::DivideHigh:case Stage::DivideLow:case Stage::MultiplyResult:return 23;case Stage::BindSource:case Stage::BindTarget:return 9;case Stage::ReadCoefficient:return 5+c.read;case Stage::Write:return 6+c.write;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::DelayChild:case Stage::SamplesChild:waiting_=true;break;case Stage::Return:next=Stage::Complete;break;case Stage::ReadRate:rate_=uint16_t(read(true,0));break;case Stage::CalculateBase:if(kind_==Kind::Delay){base_=uint16_t(rate_?0x3e800000u/rate_:0);next=Stage::ClearRemainder;}else{base_=33554u*rate_;next=Stage::DoubleBase;}break;case Stage::ClearRemainder:next=Stage::BindSource;break;case Stage::DoubleBase:base_<<=1;break;case Stage::ReadCoefficient:coefficient_=uint16_t(read(false,index_));shifts_=0;break;case Stage::ScaleCoefficient:coefficient_=uint16_t(coefficient_<<1);if(++shifts_<(kind_==Kind::Delay?4u:5u))next=Stage::ScaleCoefficient;else next=kind_==Kind::Delay?Stage::CopyBase:Stage::MultiplyResult;break;case Stage::DivideHigh:high_=coefficient_?uint16_t(base_/coefficient_):0;remainder_=coefficient_?uint16_t(base_%coefficient_):uint16_t(base_);break;case Stage::DivideLow:result_=coefficient_?uint16_t((uint32_t(remainder_)<<16)/coefficient_):0;break;case Stage::Merge:result_|=uint32_t(high_)<<16;break;case Stage::DoubleResult:result_<<=1;break;case Stage::MultiplyResult:result_=unsigned(coefficient_)*(base_>>16);next=Stage::Write;break;case Stage::Write:write(index_,result_);break;case Stage::Advance:++index_;break;case Stage::Repeat:next=index_<34?Stage::ReadCoefficient:Stage::Return;break;default:break;}stage_=next;return cost;}
private:Kind kind_;Stage stage_;bool waiting_=false;unsigned index_=0,shifts_=0;uint16_t rate_=0,coefficient_=0,high_=0,remainder_=0;uint32_t base_=0,result_=0;};
}
